// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 fuzzChangeFee, uint128 virtualBase, uint128 virtualNft, uint16 feeRate) public {
        feeRate = uint16(bound(feeRate, 0, 5000));

        virtualBase = uint128(bound(virtualBase, 0, type(uint128).max));
        virtualNft = uint128(bound(virtualNft, 1, type(uint128).max));

        bool ok;
        try c.initialize(address(0), address(0), virtualBase, virtualNft, fuzzChangeFee, feeRate, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.changeFee() == fuzzChangeFee);
        } else {
            assertTrue(ok);
        }
    }
}
